import React, { useState, useEffect, useMemo } from 'react';
import { db } from './firebase'; 
import { ref, push, onValue } from "firebase/database";
import WordCloud from 'react-d3-cloud';

function App() {
  const [userInput, setUserInput] = useState("");
  const [rawData, setRawData] = useState({});
  const [view, setView] = useState("participant");

  useEffect(() => {
    const wordRef = ref(db, 'responses/wordcloud');
    // We use a "cleanup" return to prevent memory leaks
    return onValue(wordRef, (snapshot) => {
      const data = snapshot.val();
      if (data) setRawData(data);
    });
  }, []);

  const cloudData = useMemo(() => {
    const counts = {};
    Object.values(rawData).forEach(item => {
      const text = item.text.trim();
      counts[text] = (counts[text] || 0) + 1;
    });
    return Object.keys(counts).map(word => ({
      text: word,
      value: counts[word] * 20 // Scale up for visibility
    }));
  }, [rawData]);

  const submitWord = () => {
    if (userInput.trim() !== "") {
      push(ref(db, 'responses/wordcloud'), { text: userInput.toLowerCase() });
      setUserInput("");
    }
  };

  return (
    <div style={{ padding: '20px', textAlign: 'center', fontFamily: 'Arial' }}>
      <nav style={{ marginBottom: '30px' }}>
        <button onClick={() => setView("participant")} style={{ marginRight: '10px' }}>Join Poll</button>
        <button onClick={() => setView("presenter")}>Show Cloud</button>
      </nav>

      {view === "participant" ? (
        <div>
          <h1>PLPA 265: Submit Response</h1>
          <input 
            value={userInput} 
            onChange={(e) => setUserInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && submitWord()}
            style={{ padding: '10px', fontSize: '16px', width: '250px' }}
          />
          <button onClick={submitWord} style={{ padding: '10px 20px' }}>Submit</button>
        </div>
      ) : (
        <div style={{ width: '100%', maxWidth: '800px', margin: '0 auto', border: '1px solid #ddd' }}>
          <h2>Live Classroom Cloud</h2>
          <WordCloud 
            data={cloudData} 
            width={700} 
            height={500} 
            rotate={0} // CRITICAL: Makes it instant
            padding={3}
            font="Arial"
            fontWeight="bold"
            random={() => 0.5} // Stops words from jumping positions randomly
          />
        </div>
      )}
    </div>
  );
}

export default App;
